char * xstrdup(const char *str) /* <=== xstrdup */ 
{
	size_t siz;
	size_t rsiz;
	char   *result;

	if (str == NULL) {
		return NULL;
	}
	siz = strlen(str) + 1;
	result = xmalloc(siz);

	rsiz = strlcpy(result, str, siz);
	if (rsiz)
		xassert(rsiz == siz-1);

	return result;
}

